func (q *Queries) NoteSubscriptionFailure(ctx context.Context, arg NoteSubscriptionFailureParams) (NoteSubscriptionFailureRow, error) {
	row := q.db.QueryRow(ctx, noteSubscriptionFailure, arg.DisableBefore, arg.ID, arg.OrganizationID)
	var i NoteSubscriptionFailureRow
	err := row.Scan(&i.Url, &i.FailingSince, &i.Disabled)
	return i, err
}

const retryDeadDeliveries = `-- name: RetryDeadDeliveries :execrows
UPDATE organization.webhook_deliveries d
SET delivered_at = NULL, dead_at = NULL, error = NULL, next_attempt_at = NOW(), attempt = 0,
    lease_owner = NULL, lease_until = NULL
WHERE d.id IN (
    SELECT dd.id FROM organization.webhook_deliveries dd
    JOIN organization.webhook_subscriptions sub ON sub.id = dd.subscription_id
    WHERE dd.subscription_id = $1 AND sub.organization_id = $2 AND dd.dead_at IS NOT NULL
    LIMIT $3)
`

type RetryDeadDeliveriesParams struct {
	SubscriptionID uuid.UUID
	OrganizationID uuid.UUID
	RowLimit       int32
}

// RetryDeadDeliveries re-queues, with a fresh budget of attempts, up to
// row_limit of a subscription's given-up deliveries.
func (q *Queries) RetryDeadDeliveries(ctx context.Context, arg RetryDeadDeliveriesParams) (int64, error) {
	result, err := q.db.Exec(ctx, retryDeadDeliveries, arg.SubscriptionID, arg.OrganizationID, arg.RowLimit)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const retryWebhookDelivery = `-- name: RetryWebhookDelivery :execrows
UPDATE organization.webhook_deliveries AS delivery
SET delivered_at = NULL, dead_at = NULL, error = NULL, next_attempt_at = NOW(),
    lease_owner = NULL, lease_until = NULL,
    attempt = CASE WHEN delivery.dead_at IS NOT NULL OR delivery.delivered_at IS NOT NULL
                   THEN 0 ELSE delivery.attempt END
FROM organization.webhook_subscriptions AS subscription
WHERE delivery.id = $1 AND delivery.subscription_id = subscription.id
  AND subscription.id = $2 AND subscription.organization_id = $3
  AND (delivery.lease_until IS NULL OR delivery.lease_until <= NOW())
`

type RetryWebhookDeliveryParams struct {
	DeliveryID     uuid.UUID
	SubscriptionID uuid.UUID
	OrganizationID uuid.UUID
}

// RetryWebhookDelivery re-queues one of a subscription's deliveries that no
// dispatcher holds, for now. One that had finished, delivered or given up,
// starts a fresh budget of attempts; one still retrying keeps its count.
func (q *Queries) RetryWebhookDelivery(ctx context.Context, arg RetryWebhookDeliveryParams) (int64, error) {
	result, err := q.db.Exec(ctx, retryWebhookDelivery, arg.DeliveryID, arg.SubscriptionID, arg.OrganizationID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const rotateWebhookSecret = `-- name: RotateWebhookSecret :exec
UPDATE organization.webhook_subscriptions
SET secret_ct = $1, secret_nonce = $2,
    previous_secret_ct = $3, previous_secret_nonce = $4,
    previous_secret_expires_at = $5
WHERE id = $6 AND organization_id = $7
`

type RotateWebhookSecretParams struct {
	SecretCt          []byte
	SecretNonce       []byte
	PreviousCt        []byte
	PreviousNonce     []byte
	PreviousExpiresAt *time.Time
	ID                uuid.UUID
	OrganizationID    uuid.UUID
}

// RotateWebhookSecret makes the new secret current and keeps the old one,
// signing alongside it, until previous_expires_at.
func (q *Queries) RotateWebhookSecret(ctx context.Context, arg RotateWebhookSecretParams) error {
	_, err := q.db.Exec(ctx, rotateWebhookSecret,
		arg.SecretCt,
		arg.SecretNonce,
		arg.PreviousCt,
		arg.PreviousNonce,
		arg.PreviousExpiresAt,
		arg.ID,
		arg.OrganizationID,
	)
	return err
}

const scheduleDeliveryRetry = `-- name: ScheduleDeliveryRetry :exec
UPDATE organization.webhook_deliveries
SET attempt = attempt + 1, status_code = $1, response_body = $2,
    error = $3, next_attempt_at = $4::timestamptz,
    lease_owner = NULL, lease_until = NULL
WHERE id = $5 AND lease_owner = $6::uuid
`

type ScheduleDeliveryRetryParams struct {
	StatusCode    *int32
	ResponseBody  *string
	Error         *string
	NextAttemptAt time.Time
	ID            uuid.UUID
	LeaseOwner    uuid.UUID
}

func (q *Queries) ScheduleDeliveryRetry(ctx context.Context, arg ScheduleDeliveryRetryParams) error {
	_, err := q.db.Exec(ctx, scheduleDeliveryRetry,
		arg.StatusCode,
		arg.ResponseBody,
		arg.Error,
		arg.NextAttemptAt,
		arg.ID,
		arg.LeaseOwner,
	)
	return err
}

const updateWebhookSubscription = `-- name: UpdateWebhookSubscription :one
UPDATE organization.webhook_subscriptions
SET url = COALESCE($1, url), events = COALESCE($2::text[], events)
WHERE id = $3 AND organization_id = $4
RETURNING url, events
`

type UpdateWebhookSubscriptionParams struct {
	Url            *string
	Events         []string
	ID             uuid.UUID
	OrganizationID uuid.UUID
}

type UpdateWebhookSubscriptionRow struct {
	Url    string
	Events []string
}

func (q *Queries) UpdateWebhookSubscription(ctx context.Context, arg UpdateWebhookSubscriptionParams) (UpdateWebhookSubscriptionRow, error) {
	row := q.db.QueryRow(ctx, updateWebhookSubscription,
		arg.Url,
		arg.Events,
		arg.ID,
		arg.OrganizationID,
	)
	var i UpdateWebhookSubscriptionRow
	err := row.Scan(&i.Url, &i.Events)
	return i, err
}
